+        ActionListener<ComputeResponse> rootListener = new ActionListener<>() {
+            @Override
+            public void onResponse(ComputeResponse result) {
+                assertThat(
+                    result.getProfiles().stream().collect(Collectors.toMap(p -> p, p -> 1, Integer::sum)),
