+    @Override
+    public void send(
+        Logger logger,
+        Request request,
+        HttpClientContext context,
+        Supplier<Boolean> hasRequestTimedOutFunction,
+        ResponseHandler responseHandler,
+        ActionListener<InferenceServiceResults> listener
+    ) {
