+        SecureString secureSecretKey = extractRequiredSecureString(
+            map,
+            SECRET_KEY_FIELD,
+            ModelSecrets.SECRET_SETTINGS,
+            validationException
+        );
+
+        if (validationException.validationErrors().isEmpty() == false) {
+            throw validationException;
+        }
