-            Memory filter = new Memory(len * 8);
-            ByteBuffer bbuf = filter.getByteBuffer(0, len * 8);
-            bbuf.order(ByteOrder.nativeOrder()); // little endian
-            for (SockFilter f : filters) {
-                bbuf.putShort(f.code);
-                bbuf.put(f.jt);
-                bbuf.put(f.jf);
-                bbuf.putInt(f.k);
