-        int limit,    // syscall limit (necessary for blacklisting on amd64, to ban 32-bit syscalls)
-        int fork,     // __NR_fork
-        int vfork,    // __NR_vfork
-        int execve,   // __NR_execve
-        int execveat, // __NR_execveat
-        int seccomp   // __NR_seccomp
-    ) {}
