-        // test seccomp(BOGUS)
-        long ret = linux_syscall(arch.seccomp, bogusArg);
-        if (ret != -1) {
-            throw new UnsupportedOperationException("seccomp unavailable: seccomp(BOGUS_OPERATION) returned " + ret);
