-        // test prctl(BOGUS)
-        ret = linux_prctl(bogusArg, 0, 0, 0, 0);
-        if (ret != -1) {
-            throw new UnsupportedOperationException("seccomp unavailable: prctl(BOGUS_OPTION) returned " + ret);
-        } else {
-            int errno = Native.getLastError();
-            switch (errno) {
-                case ENOSYS:
-                    break; // ok
-                case EINVAL:
